return async function basicAuth(ctx, next) {
  const requestUser = auth(ctx.req.raw)
  if (requestUser) {
    for (const user of users) {
      const [usernameEq, passwordEq] = await Promise.all([
        timingSafeEqual(user.username, requestUser.username, options.hashFunction),
        timingSafeEqual(user.password, requestUser.password, options.hashFunction),
      ])
      if (usernameEq && passwordEq) {
        await next(); return  // success
      }
    }
  }
  throw new HTTPException(401, { res })
}

return async function jwt(ctx, next) {
  const credentials = ctx.req.raw.headers.get(options.headerName || 'Authorization')
  let token
  if (credentials) {
    const parts = credentials.split(/\s+/)
    if (parts.length !== 2 || parts[0].toLowerCase() !== 'bearer')
      throw new HTTPException(401, { ... })
    else token = parts[1]
  } else if (options.cookie) {
    token = getCookie(ctx, options.cookie)
  }
  if (!token) throw new HTTPException(401, { ... })
  payload = await Jwt.verify(token, options.secret, { alg: options.alg })
  ctx.set('jwtPayload', payload); await next()
}

return async function jwk(ctx, next) {
  // extract token from header or cookie (same as jwt)
  if (!token) {
    if (options.allow_anon) return next()
    throw new HTTPException(401, { ... })
  }
  const keys = typeof options.keys === 'function'
    ? await options.keys(ctx) : options.keys
  const jwks_uri = typeof options.jwks_uri === 'function'
    ? await options.jwks_uri(ctx) : options.jwks_uri
  payload = await Jwt.verifyWithJwks(token,
    { keys, jwks_uri, allowedAlgorithms: options.alg }, init)
  if (!payload) throw new HTTPException(401, { ... })
  ctx.set('jwtPayload', payload); await next()
}

return async function cors(c, next) {
  const allowOrigin = await findAllowOrigin(c.req.header('origin') || '', c)
  if (allowOrigin) set('Access-Control-Allow-Origin', allowOrigin)
  if (opts.credentials) set('Access-Control-Allow-Credentials', 'true')
  if (exposeHeadersStr) set('Access-Control-Expose-Headers', exposeHeadersStr)
  if (c.req.method === 'OPTIONS') {
    // set allow-methods, allow-headers, max-age ...
    c.res.headers.delete('Content-Length')
    c.res.headers.delete('Content-Type')
    return new Response(null, { headers: c.res.headers, status: 204 })
  }
  await next()
  if (opts.origin !== '*') c.header('Vary', 'Origin', { append: true })
}

return async function csrf(c, next) {
  if (
    !isSafeMethodRe.test(c.req.method) &&
    isCsrfContentTypeRe.test(c.req.header('content-type') || 'text/plain') &&
    !(await isAllowedSecFetchSite(c.req.header('sec-fetch-site'), c)) &&
    !(await isAllowedOrigin(c.req.header('origin'), c))
  ) {
    const res = new Response('Forbidden', { status: 403 })
    throw new HTTPException(403, { res })
  }
  await next()
}

export const secureHeaders = (customOptions?: SecureHeadersOptions): MiddlewareHandler => {
  const options = { ...DEFAULT_OPTIONS, ...customOptions }
  const headersToSet = getFilteredHeaders(options)
  const callbacks: SecureHeadersCallback[] = []
  // build CSP and other dynamic headers ...
  return async function secureHeaders(ctx, next) {
    const headersToSetForReq =
      callbacks.length === 0 ? headersToSet
      : callbacks.reduce((acc, cb) => cb(ctx, acc), headersToSet)
    await next()
    setHeaders(ctx, headersToSetForReq, options.overwrite !== false)
    if (options?.removePoweredBy) ctx.res.headers.delete('X-Powered-By')
  }
}

return async (c, next) => {
  if (c.finalized) return next()
  if (c.req.method !== 'GET' && c.req.method !== 'HEAD') return next()
  // decode and validate path, block traversal
  let path = join(root, rewriteRequestPath ? rewriteRequestPath(filename) : filename)
  if (options.isDir && (await options.isDir(path))) path = join(path, DEFAULT_DOCUMENT)
  let content = await getContent(path, c)
  if (content != null) {
    const mimeType = getMimeType(path, options.mimes) || getMimeType(path)
    c.header('Content-Type', mimeType || 'application/octet-stream')
    // check precompressed variants ...
    return c.body(content)
  }
  await next()
}

return async function cache(c, next) {
  if ((c.req.method !== 'GET' && c.req.method !== 'QUERY')
      || c.req.raw.headers.has('Authorization')) {
    await next(); return
  }
  const key = createCacheKey(baseKey, c.req.url, cacheKeyRequest, varyHeaders)
  const cacheName = typeof options.cacheName === 'function'
    ? await options.cacheName(c) : options.cacheName
  const store = await caches.open(cacheName)
  const hit = await store.match(key)
  if (hit) return new Response(hit.body, hit)
  await next()
  if (!cacheableStatusCodes.has(c.res.status)) return
  // skip if Set-Cookie or private Cache-Control
}

export const some = (...middleware): MiddlewareHandler => {
  return async function some(c, next) {
    for (const handler of middleware) {
      try {
        const result = await handler(c, wrappedNext)
        if (result === false) { lastError = new Error('No successful middleware found'); continue }
        lastError = undefined; break
      } catch (error) {
        lastError = error
        if (isNextCalled) break
      }
    }
    if (lastError) throw lastError
  }
}

return async function timeout(context, next) {
  let timer: number | undefined
  const timeoutPromise = new Promise<void>((_, reject) => {
    timer = setTimeout(() => {
      reject(typeof exception === 'function' ? exception(context) : exception)
    }, duration) as unknown as number
  })
  try {
    await Promise.race([next(), timeoutPromise])
  } finally {
    if (timer !== undefined) clearTimeout(timer)
  }
}

const asyncLocalStorage = new AsyncLocalStorage<Context>()

export const contextStorage = (): MiddlewareHandler => {
  return async function contextStorage(c, next) {
    await asyncLocalStorage.run(c, next)
  }
}
export const getContext = <E extends Env = Env>(): Context<E> => {
  const context = asyncLocalStorage.getStore() as Context<E> | undefined
  if (!context) throw new Error('Context is not available')
  return context
}
